/**
 * Java Entity + Enum 生成器
 * IR → MyBatis-Plus 实体 + enum
 *
 * 约定：
 *   - 主键 id：默认 Long 自增（@TableId AUTO）；idType: string/uuid 时为 String
 *   - 列名走 @TableField(camelToSnake(fn))
 *   - 时间：OffsetDateTime，auto:create/update 走 @TableField(fill=...)
 *     需配合 MetaObjectHandler（handler.mjs 生成骨架）才能生效
 */
import { writeFileSync, mkdirSync, existsSync } from 'fs'
import { join } from 'path'

const HEADER = [
  '// AUTO-GENERATED by polyforge. DO NOT EDIT.',
  '// 源：模型定义',
  '',
]

// 包名由 generateJavaEntity 的 basePackage 参数派生（见文件末尾）

// 注：entity 不再有 json（C26 禁）或 array（拆子表）字段
// date 统一用 LocalDate；datetime 由调用方传入 dateTimeType
let DATE_TIME_TYPE = 'OffsetDateTime'

function camelToSnake(s) {
  return s.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase()
}

function javaType(fd) {
  if (fd.of) {
    const ofMap = { string: 'String', text: 'String', int: 'Integer', long: 'Long', number: 'BigDecimal', decimal: 'BigDecimal', boolean: 'Boolean', date: 'LocalDate', datetime: DATE_TIME_TYPE }
    if (ofMap[fd.of]) return 'List<' + ofMap[fd.of] + '>'
    if (fd.of === 'id') return 'List<Long>'
    return 'List<' + javaTypeByRef(fd.of, fd.resolvedOf) + '>'
  }
  const t = fd.type
  if (t === 'id') return fd.idType === 'long' || !fd.idType ? 'Long' : 'String'
  if (t === 'date') return 'LocalDate'
  if (t === 'datetime') return DATE_TIME_TYPE
  const map = {
    string: 'String', text: 'String', int: 'Integer', long: 'Long',
    number: 'BigDecimal', decimal: 'BigDecimal', boolean: 'Boolean',
  }
  if (map[t]) return map[t]
  return javaTypeByRef(t, fd.resolved)
}

/** 引用类型映射（enum/entity）。其余 kind 由 C3 拦截，到不了这里。 */
function javaTypeByRef(name, resolved) {
  if (resolved.kind === 'enum' || resolved.kind === 'entity') return name
  throw new Error('无法映射实体字段引用类型: ' + name + '（kind=' + resolved.kind + '）')
}

/**
 * 枚举生成：Java 常量名大写（符合惯例，供 @PreAuthorize / JWT 用），
 * 同时保留契约里的原始值，通过 @JsonValue/@JsonCreator 做 JSON 桥接。
 * 前端始终收发契约里的小写值，Java 侧仍是标准枚举。
 */
function renderEnum(name, def, PKG_ENUM) {
  const vals = def.values
  const lines = [...HEADER]
  lines.push('package ' + PKG_ENUM + ';')
  lines.push('')
  lines.push('import com.baomidou.mybatisplus.annotation.IEnum;')
  lines.push('import com.fasterxml.jackson.annotation.JsonCreator;')
  lines.push('import com.fasterxml.jackson.annotation.JsonValue;')
  lines.push('')
  if (def.description) lines.push('/** ' + def.description + ' */')
  lines.push('public enum ' + name + ' implements IEnum<String> {')
  lines.push('')
  lines.push('    ' + vals.map((v) => v.toUpperCase() + '("' + v + '")').join(',\n    ') + ';')
  lines.push('')
  lines.push('    private final String value;')
  lines.push('')
  lines.push('    ' + name + '(String value) {')
  lines.push('        this.value = value;')
  lines.push('    }')
  lines.push('')
  lines.push('    @JsonValue')
  lines.push('    public String getValue() {')
  lines.push('        return value;')
  lines.push('    }')
  lines.push('')
  lines.push('    @JsonCreator')
  lines.push('    public static ' + name + ' fromValue(String value) {')
  lines.push('        for (' + name + ' v : values()) {')
  lines.push('            if (v.value.equals(value)) return v;')
  lines.push('        }')
  lines.push('        throw new IllegalArgumentException("未知的 ' + name + ' 值: " + value);')
  lines.push('    }')
  lines.push('}')
  return lines.join('\n') + '\n'
}

function renderEntity(name, def, PKG_ENTITY, PKG_ENUM) {
  const fields = def.fields || {}
  const usedEnums = new Set()
  for (const fd of Object.values(fields)) {
    if (fd.resolved?.kind === 'enum') usedEnums.add(fd.resolved.target)
    if (fd.resolvedOf?.kind === 'enum') usedEnums.add(fd.resolvedOf.target)
  }
  const usesList = Object.values(fields).some((fd) => fd.of)

  const lines = [...HEADER]
  lines.push('package ' + PKG_ENTITY + ';')
  lines.push('')
  lines.push('import com.baomidou.mybatisplus.annotation.*;')
  lines.push('import lombok.Data;')
  if (DATE_TIME_TYPE === 'OffsetDateTime') lines.push('import java.time.OffsetDateTime;')
  else lines.push('import java.time.LocalDateTime;')
  lines.push('import java.time.LocalDate;')
  lines.push('import java.math.BigDecimal;')
  if (usesList) lines.push('import java.util.List;')
  for (const e of [...usedEnums].sort()) {
    lines.push('import ' + PKG_ENUM + '.' + e + ';')
  }
  lines.push('')
  lines.push('@Data')
  const table = def.table || camelToSnake(name) + 's'
  lines.push('@TableName("' + table + '")')
  lines.push('public class ' + name + ' {')
  lines.push('')

  for (const [fn, fd] of Object.entries(fields)) {
    if (fd.derived) continue
    if (fd.note) lines.push('    // ' + fd.note)
    if (fd.type === 'id' && !fd.ref) {
      if (!fd.idType || fd.idType === 'long') {
        lines.push('    @TableId(type = IdType.AUTO)')
      } else {
        lines.push('    @TableId')
      }
    } else if (fd.auto === 'create') {
      lines.push('    @TableField(fill = FieldFill.INSERT)')
    } else if (fd.auto === 'update') {
      lines.push('    @TableField(fill = FieldFill.INSERT_UPDATE)')
    } else {
      lines.push('    @TableField("' + camelToSnake(fn) + '")')
    }
    lines.push('    private ' + javaType(fd) + ' ' + fn + ';')
    lines.push('')
  }

  lines.push('}')
  return lines.join('\n') + '\n'
}

export function generateJavaEntity(ir, outRoot, basePackage, dateTimeType = 'OffsetDateTime') {
  DATE_TIME_TYPE = dateTimeType
  const PKG_ENUM = basePackage + '.generated.enums'
  const PKG_ENTITY = basePackage + '.generated.entity'
  const enumDir = join(outRoot, 'enums')
  const entityDir = join(outRoot, 'entity')
  if (!existsSync(enumDir)) mkdirSync(enumDir, { recursive: true })
  if (!existsSync(entityDir)) mkdirSync(entityDir, { recursive: true })

  let enumCount = 0
  for (const [name, def] of ir.enums) {
    writeFileSync(join(enumDir, name + '.java'), renderEnum(name, def, PKG_ENUM), 'utf-8')
    enumCount++
  }

  let entityCount = 0
  for (const [name, def] of ir.entities) {
    writeFileSync(join(entityDir, name + '.java'), renderEntity(name, def, PKG_ENTITY, PKG_ENUM), 'utf-8')
    entityCount++
  }

  console.log('  [java/entity] ' + enumCount + ' 个 enum + ' + entityCount + ' 个 entity → ' + outRoot)
}
